import{c as l,Q as s,j as t,m as o}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"大数据架构设计案例分析","description":"","frontmatter":{"title":"大数据架构设计案例分析"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/大数据架构设计理论与实践（第二版）/大数据架构设计案例分析.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/大数据架构设计理论与实践（第二版）/大数据架构设计案例分析.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/大数据架构设计理论与实践（第二版）/大数据架构设计案例分析.md"};function e(r,a,n,c,d,u){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="大数据架构设计案例分析" tabindex="-1">大数据架构设计案例分析 <a class="header-anchor" href="#大数据架构设计案例分析" aria-label="Permalink to &quot;大数据架构设计案例分析&quot;">​</a></h1><blockquote><p>共 8 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-在lambda架构的大数据平台中-离线计算部分主要负责处理批量数据。关于离线计算部分的技术选型和数据流向-下列描述正确的是-。" tabindex="-1">Q1. 在Lambda架构的大数据平台中，离线计算部分主要负责处理批量数据。关于离线计算部分的技术选型和数据流向，下列描述正确的是（）。 <a class="header-anchor" href="#q1-在lambda架构的大数据平台中-离线计算部分主要负责处理批量数据。关于离线计算部分的技术选型和数据流向-下列描述正确的是-。" aria-label="Permalink to &quot;Q1. 在Lambda架构的大数据平台中，离线计算部分主要负责处理批量数据。关于离线计算部分的技术选型和数据流向，下列描述正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 使用Spark和Map/Reduce进行批处理，结果存储在HDFS中，并通过Impala或Hive建立数据仓库</li><li><strong>B.</strong> 使用Spark Streaming进行实时处理，结果存储在Redis中，并通过HBase建立数据仓库</li><li><strong>C.</strong> 使用Flink进行流处理，结果存储在ElasticSearch中，并通过Kafka建立数据仓库</li><li><strong>D.</strong> 使用Storm进行批处理，结果存储在MongoDB中，并通过Cassandra建立数据仓库</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q2-关于kappa架构的特点-下列描述正确的是-。" tabindex="-1">Q2. 关于Kappa架构的特点，下列描述正确的是（）。 <a class="header-anchor" href="#q2-关于kappa架构的特点-下列描述正确的是-。" aria-label="Permalink to &quot;Q2. 关于Kappa架构的特点，下列描述正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 采用批处理和流处理两套独立的数据处理引擎</li><li><strong>B.</strong> 使用统一的数据处理引擎进行实时流数据处理</li><li><strong>C.</strong> 必须同时维护批视图和实时视图两套数据存储</li><li><strong>D.</strong> 只能处理离线批量数据，无法处理实时数据</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q3-在lambda架构的大数据处理平台中-数据计算层通常包含-三个主要部分。" tabindex="-1">Q3. 在Lambda架构的大数据处理平台中，数据计算层通常包含（）三个主要部分。 <a class="header-anchor" href="#q3-在lambda架构的大数据处理平台中-数据计算层通常包含-三个主要部分。" aria-label="Permalink to &quot;Q3. 在Lambda架构的大数据处理平台中，数据计算层通常包含（）三个主要部分。&quot;">​</a></h2><ul><li><strong>A.</strong> 离线计算、实时计算、合并计算</li><li><strong>B.</strong> 数据采集、数据清洗、数据存储</li><li><strong>C.</strong> 批处理层、加速层、服务层</li><li><strong>D.</strong> 数据输入、数据处理、数据输出</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q4-在lambda架构中-负责处理实时增量数据并提供低延迟查询响应的是-。" tabindex="-1">Q4. 在Lambda架构中，负责处理实时增量数据并提供低延迟查询响应的是（）。 <a class="header-anchor" href="#q4-在lambda架构中-负责处理实时增量数据并提供低延迟查询响应的是-。" aria-label="Permalink to &quot;Q4. 在Lambda架构中，负责处理实时增量数据并提供低延迟查询响应的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 批处理层（Batch layer）</li><li><strong>B.</strong> 加速层（Speed layer）</li><li><strong>C.</strong> 服务层（Serving layer）</li><li><strong>D.</strong> 存储层（Storage layer）</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q5-在lambda架构的大数据平台中-实时计算部分采用spark-streaming处理实时增量数据的主要目的是-。" tabindex="-1">Q5. 在Lambda架构的大数据平台中，实时计算部分采用Spark Streaming处理实时增量数据的主要目的是（）。 <a class="header-anchor" href="#q5-在lambda架构的大数据平台中-实时计算部分采用spark-streaming处理实时增量数据的主要目的是-。" aria-label="Permalink to &quot;Q5. 在Lambda架构的大数据平台中，实时计算部分采用Spark Streaming处理实时增量数据的主要目的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 将处理结果更新到实时视图</li><li><strong>B.</strong> 将处理结果写入HDFS存储</li><li><strong>C.</strong> 对历史批量数据进行周期性处理</li><li><strong>D.</strong> 合并批视图和实时视图生成最终数据集</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q6-在lambda架构中-哪个部分负责处理实时增量数据并更新实时视图-。" tabindex="-1">Q6. 在Lambda架构中，哪个部分负责处理实时增量数据并更新实时视图（ ）。 <a class="header-anchor" href="#q6-在lambda架构中-哪个部分负责处理实时增量数据并更新实时视图-。" aria-label="Permalink to &quot;Q6. 在Lambda架构中，哪个部分负责处理实时增量数据并更新实时视图（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 离线计算部分</li><li><strong>B.</strong> 实时计算部分</li><li><strong>C.</strong> 合并计算部分</li><li><strong>D.</strong> 批处理部分</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q7-【问题1】-12分-分析该系统架构-从下列选项中选择对应的选项填入-1-6-中。a-lvs-b-http-https-c-dubbo-d-quartz-e-mongdb-f-es-client" tabindex="-1">Q7. 【问题1】（12分）分析该系统架构，从下列选项中选择对应的选项填入（1）-（6）中。A．LVS B.HTTP/HTTPS C.DUBBO D.Quartz E.MongDB F. ES Client <a class="header-anchor" href="#q7-【问题1】-12分-分析该系统架构-从下列选项中选择对应的选项填入-1-6-中。a-lvs-b-http-https-c-dubbo-d-quartz-e-mongdb-f-es-client" aria-label="Permalink to &quot;Q7. 【问题1】（12分）分析该系统架构，从下列选项中选择对应的选项填入（1）-（6）中。A．LVS B.HTTP/HTTPS C.DUBBO D.Quartz E.MongDB F. ES Client&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题五（共25分）请详细阅读有关Web架构设计方面的叙述，在答题纸上回答问题1至问题3。【说明】阅读以下关于 Web 应用设计开发的描述，在答题纸上回答问题 1 至问题 3。【说明】某电商公司拟开发一个可以支持亿级流量的系统。公司架构师张工认为应该采用B/S技术实现系统开发。王工认为采用当前主流的微服务架构可以更好的支持高并发的场景应用。公司经过讨论分析最终采用了王工的建议。其系统的架构如下图所示的设计。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>【参考答案】（1）A ；（2）B；（3）C ；（4）D；（5）F；（6）E。</p></div></details><h2 id="q8-【问题1】-10分-针对李工提出的改进方案-从-a-j-中分别选出各技术的相关描述和对应常见支持软件填入表-5-1-中的-1-10-处。a-保存静态文件-减少网络交换量-加速响应请求b-可采用软件级和硬件级负载均衡实现分流和后台减压c-文件存储系统-快速查找文件d-fastdfse-haproxyf-jbossg-hadoop-distributed-file-system-hdfs-h-apache-tomacti-squidj-mongodb" tabindex="-1">Q8. 【问题1】（10分）针对李工提出的改进方案，从 a～j 中分别选出各技术的相关描述和对应常见支持软件填入表 5-1 中的（1）～（10）处。a）保存静态文件，减少网络交换量，加速响应请求b）可采用软件级和硬件级负载均衡实现分流和后台减压c）文件存储系统，快速查找文件d）FastDFSe）HAProxyf）JBossg）Hadoop Distributed File System（HDFS）h）Apache Tomacti）Squidj）MongoDB <a class="header-anchor" href="#q8-【问题1】-10分-针对李工提出的改进方案-从-a-j-中分别选出各技术的相关描述和对应常见支持软件填入表-5-1-中的-1-10-处。a-保存静态文件-减少网络交换量-加速响应请求b-可采用软件级和硬件级负载均衡实现分流和后台减压c-文件存储系统-快速查找文件d-fastdfse-haproxyf-jbossg-hadoop-distributed-file-system-hdfs-h-apache-tomacti-squidj-mongodb" aria-label="Permalink to &quot;Q8. 【问题1】（10分）针对李工提出的改进方案，从 a～j 中分别选出各技术的相关描述和对应常见支持软件填入表 5-1 中的（1）～（10）处。a）保存静态文件，减少网络交换量，加速响应请求b）可采用软件级和硬件级负载均衡实现分流和后台减压c）文件存储系统，快速查找文件d）FastDFSe）HAProxyf）JBossg）Hadoop Distributed File System（HDFS）h）Apache Tomacti）Squidj）MongoDB&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题五（25分）阅读以下关于Web系统架构设计的叙述，在答题纸上回答问题 1~3。【说明】某公司自主研发的网络教学平台因业务扩展，导致系统访问量不断增大，现有系统访问速度缓慢，有时甚至出现系统故障瘫痪等现象。面对这一情况，公司召开项目组讨论会议，寻求该商务平台的改进方案。讨论会上，王工提出可以利用镜像站点、CDN 内容分发等方式解决并发访问量带来的问题。而李工认为，仅仅依靠上述外网加速技术不能完全解决系统现有问题，如果访问量持续增加，系统仍存在崩溃的可能。李工提出应同时结合 Web 内网加速技术优化系统改进方案，如综合应用负载均衡、缓存服务器、Web应用服务器、分布式文件系统、分布式数据库等。经过讨论，公司最终决定采用李工的思路，完成改进系统的设计方案。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>（1）（b） （2）（e） （3）（a） （4）（i） （5）（c）（6）（d） （7）（g） （8）（f） （9）（h） （10）（j）（6）和（7）、 （8）和（9）的答案可互换。</p></div></details>',26)])])}const g=l(i,[["render",e]]);export{p as __pageData,g as default};
